import numpy as np
# represent test clues grouped by r+c
G=[[0,7,0,5,6,0,0,8,0],[7,0,5,6,0,0,8,0,0],[0,5,6,0,0,8,0,0,7],[5,6,0,0,8,0,0,7,0],[6,0,0,8,0,0,7,0,0],[0,0,8,0,0,7,0,0,1],[0,8,0,0,7,0,0,1,8],[8,0,0,7,0,0,1,8,0],[0,0,7,0,0,1,8,0,8]]
from collections import defaultdict
sums=defaultdict(set)
for r,row in enumerate(G):
 for c,v in enumerate(row):
  if v:sums[r+c].add(v)
print(dict(sorted(sums.items())))

program = '''def transform(grid):
    h, w = len(grid), len(grid[0])

    # Candidate stripe coordinates: horizontal, vertical, and the two diagonals.
    funcs = {
        "row": lambda r, c: r,
        "col": lambda r, c: c,
        "sum": lambda r, c: r + c,
        "diff": lambda r, c: r - c,
    }
    def positions(kind, key):
        if kind == "row":
            return [(key, c) for c in range(w)]
        if kind == "col":
            return [(r, key) for r in range(h)]
        if kind == "sum":
            return [(r, key-r) for r in range(h) if 0 <= key-r < w]
        return [(r, r-key) for r in range(h) if 0 <= r-key < w]

    candidates = []
    for kind, coord in funcs.items():
        groups = {}
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    groups.setdefault(coord(r, c), []).append(v)
        anchors = {}
        for key, vals in groups.items():
            cells = positions(kind, key)
            if len(vals) == len(cells) and len(set(vals)) == 1:
                anchors[key] = vals[0]
        if len(anchors) >= 2:
            candidates.append((len(anchors), kind, anchors))

    if not candidates:
        return [row[:] for row in grid]
    _, kind, anchors = max(candidates, key=lambda item: item[0])
    keys = list(anchors)
    span = max(keys) - min(keys) + 1
    period = None
    stripe = None
    for p in range(1, span + 1):
        residues = {}
        consistent = True
        for key, color in anchors.items():
            r = key % p
            if r in residues and residues[r] != color:
                consistent = False
                break
            residues[r] = color
        if consistent and len(residues) == p:
            period, stripe = p, residues
            break
    if period is None:
        # Fall back to the smallest consistent period if some stripe is not represented.
        for p in range(1, span + 1):
            residues = {}
            for key, color in anchors.items():
                r = key % p
                if r in residues and residues[r] != color:
                    break
                residues[r] = color
            else:
                period, stripe = p, residues
                break
    if period is None:
        return [row[:] for row in grid]

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            key = funcs[kind](r, c)
            row.append(stripe[key % period])
        out.append(row)
    return out
'''
prog.parent.mkdir(parents=True, exist_ok=True)
prog.write_text(program)
